#[tokio::test]
async fn test_hud_publish_zone_ttl_sets_content_expiry_and_is_swept() {
    let (server, clock) = server();
    call(
        &server,
        "hud_publish",
        json!({"surface": "zone:subtitle", "content": "expiring", "ttl_ms": 20000}),
    )
    .await;
    let mut scene = server.scene.lock().await;
    let rec = &scene.zone_registry.active_publishes["subtitle"][0];
    assert_eq!(
        rec.expires_at_wall_us,
        Some(21_000_000),
        "ttl_ms becomes an absolute expiry in µs"
    );
    clock.advance(19_000);
    assert_eq!(scene.drain_expired_zone_publications(), 0);
    clock.advance(1_000);
    assert_eq!(scene.drain_expired_zone_publications(), 1);
    assert!(
        scene
            .zone_registry
            .active_publishes
            .get("subtitle")
            .is_none_or(Vec::is_empty)
    );
}

#[tokio::test]
async fn delay_ms_holds_content_until_due() {
    let (server, clock) = server();
    let v = call(
        &server,
        "hud_publish",
        json!({"surface": "zone:subtitle", "content": "later", "delay_ms": 5000, "ttl_ms": 1000}),
    )
    .await;
    assert_eq!(v["expires_in_ms"], 6000);
    let mut scene = server.scene.lock().await;
    scene.apply_due_batches();
    assert!(
        scene
            .zone_registry
            .active_publishes
            .get("subtitle")
            .is_none_or(Vec::is_empty),
        "not shown before present_at"
    );
    clock.advance(5_000);
    scene.apply_due_batches();
    let rec = &scene.zone_registry.active_publishes["subtitle"][0];
    assert_eq!(
        rec.expires_at_wall_us,
        Some(7_000_000),
        "expiry counts from presentation"
    );
}

/// A delayed notification takes the same expiry as an immediate one: held
/// for `ttl_ms:0` (and `hud_hold` then retimes it once it has materialized),
/// otherwise the explicit expiry stamped at schedule time (the 60 s
/// `DEFAULT_ZONE_TTL_MS` when `ttl_ms` is absent), counted from presentation.
/// That case is unchanged from before the fix.

#[tokio::test]
async fn notification_ttl_zero_is_held_and_hold_retimes_it() {
    let (server, clock) = server();
    let notif = json!({"surface": "zone:notification-area",
        "content": {"title": "t", "body": "b"}});
    let mut held = notif.clone();
    held["ttl_ms"] = json!(0);
    let v = call(&server, "hud_publish", held).await;
    assert_eq!(v, json!({"ok": true}));
    {
        let mut scene = server.scene.lock().await;
        let rec = &scene.zone_registry.active_publishes["notification-area"][0];
        assert_eq!(rec.expires_at_wall_us, None, "no urgency-derived expiry");
        clock.advance(120_000);
        assert_eq!(scene.drain_expired_zone_publications(), 0);
    }
    // Hold with a ttl counts from now; hold 0 releases it again.
    let v = call(
        &server,
        "hud_hold",
        json!({"surface": "zone:notification-area", "ttl_ms": 5000}),
    )
    .await;
    assert_eq!(v, json!({"ok": true, "expires_in_ms": 5000}));
    {
        let scene = server.scene.lock().await;
        assert_eq!(
            scene.zone_registry.active_publishes["notification-area"][0].expires_at_wall_us,
            Some(scene.now_wall_us() + 5_000_000)
        );
    }
    // A shorter hold replaces the expiry (it is not the later of old and new).
    call(
        &server,
        "hud_hold",
        json!({"surface": "zone:notification-area", "ttl_ms": 1000}),
    )
    .await;
    {
        let scene = server.scene.lock().await;
        assert_eq!(
            scene.zone_registry.active_publishes["notification-area"][0].expires_at_wall_us,
            Some(scene.now_wall_us() + 1_000_000)
        );
    }
    call(
        &server,
        "hud_hold",
        json!({"surface": "zone:notification-area", "ttl_ms": 0}),
    )
    .await;
    {
        let mut scene = server.scene.lock().await;
        clock.advance(120_000);
        assert_eq!(scene.drain_expired_zone_publications(), 0);
    }
    call(
        &server,
        "hud_clear",
        json!({"surface": "zone:notification-area"}),
    )
    .await;
    let scene = server.scene.lock().await;
    assert!(
        scene
            .zone_registry
            .active_publishes
            .get("notification-area")
            .is_none_or(Vec::is_empty)
    );
}

#[test]
fn widget_ttl_only_expired_publication_removed_when_mixed() {
    let (mut scene, _tab, clock) =
        scene_with_gauge_and_clock(ContentionPolicy::Stack { max_depth: 10 });

    let now_us = 1_000_000u64; // clock starts at t=1 000 ms
    let expires_soon = now_us + 500_000u64; // expires in 500 ms

    // Publish the soon-to-expire record first.
    scene
        .publish_to_widget(
            "gauge",
            std::collections::HashMap::from([(
                "level".to_string(),
                WidgetParameterValue::F32(0.1),
            )]),
            "agent.short",
            None,
            0,
            Some(expires_soon),
        )
        .unwrap();

    // Publish a permanent record (no expiry).
    scene
        .publish_to_widget(
            "gauge",
            std::collections::HashMap::from([(
                "level".to_string(),
                WidgetParameterValue::F32(0.9),
            )]),
            "agent.permanent",
            None,
            0,
            None,
        )
        .unwrap();

    assert_eq!(
        scene.widget_registry.active_for_widget("gauge").len(),
        2,
        "both publications should be present before expiry"
    );

    // Advance clock past the short expiry.
    clock.advance(600);

    let removed = scene.drain_expired_widget_publications();
    assert_eq!(removed, 1, "only the TTL publication should expire");

    let remaining = scene.widget_registry.active_for_widget("gauge");
    assert_eq!(remaining.len(), 1, "one publication should remain");
    assert_eq!(
        remaining[0].publisher_namespace, "agent.permanent",
        "the permanent publication should survive"
    );
}

/// WHEN drain_expired_widget_publications removes a publication THEN the
/// scene version is incremented.
///
/// Source: widget-system/spec.md §Requirement: Expiration Policy.

#[test]
fn test_publication_ttl_ms_uses_expires_at_wall_us() {
    // Warning notification (urgency 2): published at t=0, expires at t=15s.
    // Expected: 15_000 ms - 150 ms fade = 14_850 ms until fade starts.
    let record_warning = ZonePublishRecord {
        lease_id: None,
        zone_name: "alert-banner".to_string(),
        publisher_namespace: "agent-warn".to_string(),
        content: ZoneContent::Notification(NotificationPayload {
            text: "Disk space low".to_owned(),
            icon: String::new(),
            urgency: 2,
            ttl_ms: None, // No per-notification TTL — urgency path sets expires_at
            title: String::new(),
            actions: Vec::new(),
        }),
        published_at_wall_us: 0,
        merge_key: None,
        expires_at_wall_us: Some(15_000_000), // 15 s in µs
        content_classification: None,
        breakpoints: Vec::new(),
    };
    let ttl =
        Compositor::publication_fade_delay_ms(&record_warning, record_warning.published_at_wall_us);
    assert_eq!(
        ttl,
        Some(14_850),
        "publication_fade_delay_ms must derive 14_850 ms (15_000 - 150 fade) for a 15s warning"
    );

    // Critical notification (urgency 3): published at t=0, expires at t=30s.
    // Expected: 30_000 ms - 150 ms fade = 29_850 ms until fade starts.
    let record_critical = ZonePublishRecord {
        lease_id: None,
        zone_name: "alert-banner".to_string(),
        publisher_namespace: "agent-crit".to_string(),
        content: ZoneContent::Notification(NotificationPayload {
            text: "System failure".to_owned(),
            icon: String::new(),
            urgency: 3,
            ttl_ms: None,
            title: String::new(),
            actions: Vec::new(),
        }),
        published_at_wall_us: 0,
        merge_key: None,
        expires_at_wall_us: Some(30_000_000), // 30 s in µs
        content_classification: None,
        breakpoints: Vec::new(),
    };
    let ttl_crit = Compositor::publication_fade_delay_ms(
        &record_critical,
        record_critical.published_at_wall_us,
    );
    assert_eq!(
        ttl_crit,
        Some(29_850),
        "publication_fade_delay_ms must derive 29_850 ms (30_000 - 150 fade) for a 30s critical"
    );

    // expires_at_wall_us takes priority over per-notification ttl_ms.
    // published=1s, expires=16s → duration=15s → 15_000 - 150 = 14_850 ms until fade.
    let record_both = ZonePublishRecord {
        lease_id: None,
        zone_name: "alert-banner".to_string(),
        publisher_namespace: "agent-both".to_string(),
        content: ZoneContent::Notification(NotificationPayload {
            text: "Both set".to_owned(),
            icon: String::new(),
            urgency: 2,
            ttl_ms: Some(5_000), // explicit 5 s TTL on the notification itself
            title: String::new(),
            actions: Vec::new(),
        }),
        published_at_wall_us: 1_000_000, // published at t=1s
        merge_key: None,
        expires_at_wall_us: Some(16_000_000), // expires at t=16s → 15 s duration
        content_classification: None,
        breakpoints: Vec::new(),
    };
    let ttl_both =
        Compositor::publication_fade_delay_ms(&record_both, record_both.published_at_wall_us);
    assert_eq!(
        ttl_both,
        Some(14_850),
        "publication_fade_delay_ms must prefer expires_at_wall_us over per-notification ttl_ms (14_850 ms = 15_000 - 150)"
    );

    // No expires_at: held until cleared, whatever the payload ttl_ms says.
    let record_info = ZonePublishRecord {
        lease_id: None,
        zone_name: "alert-banner".to_string(),
        publisher_namespace: "agent-info".to_string(),
        content: ZoneContent::Notification(NotificationPayload {
            text: "All good".to_owned(),
            icon: String::new(),
            urgency: 1,
            ttl_ms: Some(8_000),
            title: String::new(),
            actions: Vec::new(),
        }),
        published_at_wall_us: 0,
        merge_key: None,
        expires_at_wall_us: None,
        content_classification: None,
        breakpoints: Vec::new(),
    };
    let ttl_info = Compositor::publication_fade_delay_ms(&record_info, 0);
    assert_eq!(
        ttl_info, None,
        "a record with no expiry is held and has no fade delay"
    );
}

// ── Transition interrupt semantics [hud-hzub.2] ─────────────────────────

/// fade_in_from starts from a non-zero opacity.
///
/// Acceptance criterion: transition interrupt semantics must begin fade-in
/// from current composite opacity, not from zero.

#[tokio::test]
async fn hold_moves_the_fade_deadline_and_ttl_zero_never_fades() {
    use std::sync::Arc;
    use std::time::Duration;
    use tze_hud_scene::clock::TestClock;

    let (mut compositor, _surface) = require_gpu!(make_compositor_and_surface(320, 200).await);
    let clock = Arc::new(TestClock::new(1_000));
    let mut scene =
        countdown_notification_scene_on(SceneGraph::new_with_clock(1280.0, 720.0, clock.clone()));
    let delay = |c: &Compositor| {
        let states: Vec<_> = c.pub_animation_states["notification-area"]
            .values()
            .collect();
        assert_eq!(states.len(), 1);
        states[0].ttl_ms
    };
    compositor.update_publication_animations(&scene);
    assert_eq!(
        delay(&compositor),
        Some(7_850),
        "urgency default, 8 s - fade"
    );

    // 5 s in, hold 20 s: the fade is due 19.85 s from now, one deadline.
    clock.advance(5_000);
    let first_deadline = compositor.next_animation_deadline().unwrap();
    assert!(scene.hold_zone_publications("notification-area", "agent-a", Some(20_000_000)));
    compositor.update_publication_animations(&scene);
    assert_eq!(delay(&compositor), Some(19_850));
    let moved = compositor.next_animation_deadline().unwrap();
    assert!(
        moved > first_deadline + Duration::from_secs(10),
        "deadline moved out"
    );
    assert!(
        !compositor.has_inflight_animation(&scene),
        "still just counting down"
    );

    // ttl_ms:0 holds: no deadline, no animation, past auto_clear_ms and the sweep.
    assert!(scene.hold_zone_publications("notification-area", "agent-a", None));
    compositor.update_publication_animations(&scene);
    assert_eq!(delay(&compositor), None);
    assert_eq!(
        compositor.next_animation_deadline(),
        None,
        "held schedules no wake"
    );
    clock.advance(60_000);
    assert_eq!(
        scene.drain_expired_zone_publications(),
        0,
        "scene sweep keeps it"
    );
    compositor.update_publication_animations(&scene);
    assert!(!compositor.has_inflight_animation(&scene));
    assert_eq!(
        compositor.pub_opacity(
            "notification-area",
            &scene.zone_registry.active_publishes["notification-area"][0]
        ),
        1.0
    );

    // hud_clear removes it.
    scene
        .clear_zone_for_publisher("notification-area", "agent-a")
        .unwrap();
    compositor.update_publication_animations(&scene);
    assert!(
        compositor
            .pub_animation_states
            .values()
            .all(|zone| zone.is_empty())
    );
    assert_eq!(compositor.next_animation_deadline(), None);
}

#[tokio::test]
async fn grpc_zone_publish_ttl_sets_expiry_and_is_swept() {
    let clock = wall_aligned_clock();
    let (tx, mut stream, state, server, _client) = zone_publisher(clock.clone()).await;

    let ack = publish_and_ack(&tx, &mut stream, 2, subtitle_publish("brief", 8_000, 0, 0)).await;
    assert!(ack.ok, "{ack:?}");

    let st = state.lock().await;
    let mut scene = st.scene.lock().await;
    let now_us = scene.now_wall_us();
    let record = &scene.zone_registry.active_publishes["subtitle"][0];
    assert_eq!(record.expires_at_wall_us, Some(now_us + 8_000_000));
    clock.advance(7_999);
    scene.drain_expired_zone_publications();
    assert_eq!(subtitle_texts(&scene), vec!["brief".to_string()]);
    clock.advance(2);
    scene.drain_expired_zone_publications();
    assert!(
        subtitle_texts(&scene).is_empty(),
        "expired content is swept"
    );
    drop(scene);
    drop(st);
    server.abort();
}

/// Invariant 1: ZonePublish `expires_at_wall_us` is honored as an absolute
/// content expiry.

#[tokio::test]
async fn grpc_zone_publish_expires_at_is_swept() {
    let clock = wall_aligned_clock();
    let (tx, mut stream, state, server, _client) = zone_publisher(clock.clone()).await;
    let expires_at = clock.now_us() + 3_000_000;

    let ack = publish_and_ack(
        &tx,
        &mut stream,
        2,
        subtitle_publish("until", 0, 0, expires_at),
    )
    .await;
    assert!(ack.ok, "{ack:?}");

    let st = state.lock().await;
    let mut scene = st.scene.lock().await;
    assert_eq!(
        scene.zone_registry.active_publishes["subtitle"][0].expires_at_wall_us,
        Some(expires_at)
    );
    clock.advance(3_001);
    scene.drain_expired_zone_publications();
    assert!(subtitle_texts(&scene).is_empty());
    drop(scene);
    drop(st);
    server.abort();
}

/// Invariant 1: a ZonePublish with a future `present_at` is accepted but not
/// shown until due; it then carries its ttl from the presentation time.

#[tokio::test]
async fn grpc_zone_publish_present_at_is_held_until_due() {
    let clock = wall_aligned_clock();
    let (tx, mut stream, state, server, _client) = zone_publisher(clock.clone()).await;
    let present_at = clock.now_us() + 5_000_000;

    let ack = publish_and_ack(
        &tx,
        &mut stream,
        2,
        subtitle_publish("later", 2_000, present_at, 0),
    )
    .await;
    assert!(ack.ok, "{ack:?}");

    let st = state.lock().await;
    let mut scene = st.scene.lock().await;
    assert!(subtitle_texts(&scene).is_empty(), "not shown early");
    assert_eq!(scene.next_timed_content_wall_us(), Some(present_at));
    clock.advance(4_999);
    assert!(scene.apply_due_batches().is_empty());
    assert!(subtitle_texts(&scene).is_empty(), "still not due");
    clock.advance(1);
    let applied = scene.apply_due_batches();
    assert_eq!(applied.len(), 1);
    assert!(applied[0].applied);
    assert_eq!(subtitle_texts(&scene), vec!["later".to_string()]);
    assert_eq!(
        scene.zone_registry.active_publishes["subtitle"][0].expires_at_wall_us,
        Some(present_at + 2_000_000)
    );
    drop(scene);
    drop(st);
    server.abort();
}

/// Connect a tile agent with a lease and one tile on an active tab.
async fn tile_agent(
    clock: tze_hud_scene::TestClock,
) -> (
    tokio::sync::mpsc::Sender<ClientMessage>,
    tonic::Streaming<ServerMessage>,
    Arc<tokio::sync::Mutex<crate::session::SharedState>>,
    tokio::task::JoinHandle<()>,
    (Vec<u8>, Vec<u8>),
    HudSessionClient<tonic::transport::Channel>,
) {
    let (mut client, server, state, _exp) = setup_test_with_lease_expiry_clock(clock).await;
    {
        let st = state.lock().await;
        let mut scene = st.scene.lock().await;
        let tab = scene.create_tab("Main", 0).unwrap();
        scene.active_tab = Some(tab);
    }
    let (tx, _init, mut stream) = handshake_with_psk(&mut client, "tile-agent", "test-key").await;
    tx.send(ClientMessage {
        sequence: 2,
        timestamp_wall_us: now_wall_us(),
        payload: Some(ClientPayload::ClaimTile(ClaimTile {
            ttl_ms: 600_000,
            ..Default::default()
        })),
    })
    .await
    .unwrap();
    let claimed = match next_server_msg(&mut stream).await.payload {
        Some(ServerPayload::RequestResult(r)) if r.ok => (r.lease_id, r.ids[0].clone()),
        other => panic!("expected ClaimTile result, got {other:?}"),
    };
    (tx, stream, state, server, claimed, client)
}

fn set_root_proto(tile_id: &[u8]) -> crate::proto::MutationProto {
    let node = Node {
        layout: Default::default(),
        id: SceneId::new(),
        children: vec![],
        data: NodeData::SolidColor(SolidColorNode {
            color: Rgba::new(0.2, 0.4, 0.6, 1.0),
            bounds: Rect::new(0.0, 0.0, 120.0, 48.0),
            radius: None,
        }),
    };
    crate::proto::MutationProto {
        mutation: Some(crate::proto::mutation_proto::Mutation::SetTileRoot(
            crate::proto::SetTileRootMutation {
                tile_id: tile_id.to_vec(),
                node: Some(crate::convert::scene_node_to_proto(&node)),
            },
        )),
    }
}

async fn send_batch(
    tx: &tokio::sync::mpsc::Sender<ClientMessage>,
    stream: &mut tonic::Streaming<ServerMessage>,
    sequence: u64,
    lease_id: &[u8],
    mutations: Vec<crate::proto::MutationProto>,
    timing: Option<TimingHints>,
) -> ServerMessage {
    tx.send(ClientMessage {
        sequence,
        timestamp_wall_us: now_wall_us(),
        payload: Some(ClientPayload::MutationBatch(MutationBatch {
            batch_id: uuid::Uuid::now_v7().as_bytes().to_vec(),
            lease_id: lease_id.to_vec(),
            mutations,
            timing,
        })),
    })
    .await
    .unwrap();
    next_server_msg(stream).await
}

/// Invariant 1: a MutationBatch with a future `present_at` is accepted but
/// held; the tile's content appears only once the batch is due.

#[tokio::test]
async fn grpc_batch_present_at_holds_content_until_due() {
    let clock = wall_aligned_clock();
    let (tx, mut stream, state, server, (lease_id, tile_id_bytes), _client) =
        tile_agent(clock.clone()).await;
    let tile_id = bytes_to_scene_id(&tile_id_bytes).unwrap();

    let present_at = clock.now_us() + 5_000_000;
    let timing = Some(TimingHints {
        present_at_wall_us: present_at,
        expires_at_wall_us: 0,
    });
    match send_batch(
        &tx,
        &mut stream,
        4,
        &lease_id,
        vec![set_root_proto(&tile_id_bytes)],
        timing,
    )
    .await
    .payload
    {
        Some(ServerPayload::RequestResult(r)) => assert!(r.ok, "{r:?}"),
        other => panic!("expected MutationResult, got {other:?}"),
    }

    let st = state.lock().await;
    let mut scene = st.scene.lock().await;
    assert!(scene.tiles[&tile_id].root_node.is_none(), "not shown early");
    clock.advance(4_999);
    assert!(scene.apply_due_batches().is_empty());
    assert!(scene.tiles[&tile_id].root_node.is_none());
    clock.advance(1);
    let applied = scene.apply_due_batches();
    assert!(applied[0].applied, "{:?}", applied[0].error);
    assert!(scene.tiles[&tile_id].root_node.is_some(), "shown when due");
    drop(scene);
    drop(st);
    server.abort();
}

/// Invariant 1: a MutationBatch `expires_at` stamps the tiles it targets, and
/// the runtime sweep removes them on schedule.

#[tokio::test]
async fn grpc_batch_expires_at_sweeps_tile() {
    let clock = wall_aligned_clock();
    let (tx, mut stream, state, server, (lease_id, tile_id_bytes), _client) =
        tile_agent(clock.clone()).await;
    let tile_id = bytes_to_scene_id(&tile_id_bytes).unwrap();
    let expires_at = clock.now_us() + 8_000_000;
    let timing = Some(TimingHints {
        present_at_wall_us: 0,
        expires_at_wall_us: expires_at,
    });
    match send_batch(
        &tx,
        &mut stream,
        3,
        &lease_id,
        vec![set_root_proto(&tile_id_bytes)],
        timing,
    )
    .await
    .payload
    {
        Some(ServerPayload::RequestResult(r)) => assert!(r.ok, "{r:?}"),
        other => panic!("expected RequestResult, got {other:?}"),
    }

    let st = state.lock().await;
    let mut scene = st.scene.lock().await;
    assert_eq!(scene.tiles[&tile_id].expires_at, Some(expires_at));
    assert_eq!(scene.next_timed_content_wall_us(), Some(expires_at));
    clock.advance(7_999);
    assert!(scene.drain_expired_tiles().is_empty());
    clock.advance(2);
    assert_eq!(scene.drain_expired_tiles(), vec![tile_id]);
    assert_eq!(scene.tile_count(), 0);
    drop(scene);
    drop(st);
    server.abort();
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn poc_zone_notification_ttl_disappears_unattended() {
    let mut poc = Poc::boot().await;
    let publish = poc
        .call(
            "hud_publish",
            json!({
                "surface": NOTIFICATION,
                "content": {"title": "Build", "body": "main is green"},
                "ttl_ms": 8_000,
            }),
        )
        .await;
    assert_eq!(publish.body, json!({"ok": true, "expires_in_ms": 8_000}));
    assert!(
        publish.model_tokens <= ZONE_PUBLISH_BUDGET,
        "zone publish took {} model-visible tokens (budget {ZONE_PUBLISH_BUDGET})",
        publish.model_tokens
    );
    let held = poc.surface(NOTIFICATION).await.expect("zone listed");
    assert_eq!(held["held"], true);
    assert_eq!(poc.shown(NOTIFICATION), 1);

    // Nobody calls again: the runtime alone takes it down at the TTL.
    poc.advance(7_999).await;
    assert_eq!(poc.shown(NOTIFICATION), 1);
    poc.advance(1).await;
    assert_eq!(poc.shown(NOTIFICATION), 0);
    let released = poc.surface(NOTIFICATION).await.expect("zone listed");
    assert_eq!(released.get("held"), None, "{released}");
}

