            .unwrap()
            .block_on(async {
                tokio::time::timeout(std::time::Duration::from_secs(1), notices.recv()).await
            })
            .expect("the dismissed tile's owner is notified")
            .expect("notice");
        assert_eq!(notice.lease_id, lease_id);
        assert_eq!(notice.terminal_state, LeaseState::Revoked);
        assert_eq!(notice.removed_tiles, vec![tile_id]);
    }

    /// Install one ordinary focused button (not a portal composer/control) and
    /// return its ids plus a receiver for the runtime's real input-event channel.
    fn install_button(
        harness: &mut HeadlessEventLoopHarness,
        initially_focused: bool,
    ) -> (
        SceneId,
        SceneId,
        tze_hud_protocol::session_server::InputEventReceiver,
    ) {
        let mut scene = SceneGraph::new(1920.0, 1080.0);
        let tab_id = scene.create_tab("Main", 0).unwrap();
        let lease_id = scene.grant_lease("command-agent", 60_000);
        let tile_id = scene
            .create_tile(
                tab_id,
                "command-agent",
                lease_id,
                Rect::new(0.0, 0.0, 400.0, 200.0),
                1,
            )
            .unwrap();
        let node_id = SceneId::new();
        scene
            .set_tile_root(
                tile_id,
                Node {
                    layout: Default::default(),
                    id: node_id,
                    children: vec![],
                    data: NodeData::HitRegion(HitRegionNode {
                        bounds: Rect::new(10.0, 10.0, 160.0, 48.0),
                        interaction_id: "primary-action".to_string(),
                        accepts_focus: true,
                        accepts_pointer: true,
                        ..Default::default()
                    }),
                },
            )
            .unwrap();

        harness.app.state.focus_manager.add_tab(tab_id);
        if initially_focused {
            // Use the direct command-focus helper so no PointerDown pre-sets
            // `pressed`; ACTIVATE must be the operation that changes it.
            let _ = harness
                .app
                .state
                .focus_manager
                .focus_node_via_command(tab_id, tile_id, node_id, &scene);
        }

        {
            let shared = harness.app.state.shared_state.blocking_lock();
            *shared.scene.blocking_lock() = scene;
        }
        *harness.app.state.active_tab_mirror.lock().unwrap() = Some(tab_id);

        let tx = tze_hud_protocol::session_server::InputEventSender::new(16);
        let rx = tx.subscribe_all();
        harness.app.state.input_event_tx = Some(tx);
        (tile_id, node_id, rx)
    }

    fn received_events(
        rx: &mut tze_hud_protocol::session_server::InputEventReceiver,
    ) -> Vec<(String, ProtoInputEvent)> {
        let mut events = Vec::new();
        while let Ok((namespace, batch)) = rx.try_recv() {
            events.extend(
                batch
                    .events
                    .into_iter()
                    .filter_map(|envelope| envelope.event)
                    .map(|event| (namespace.clone(), event)),
            );
        }
        events
    }

    /// Install two scrollable tiles with keyboard focus on the first while the
    /// cursor is over the second. This is the adversarial setup for keyboard
    /// scroll ownership: focus and pointer location deliberately disagree.
    fn install_conflicting_focus_and_pointer_scroll_tiles(
        harness: &mut HeadlessEventLoopHarness,
    ) -> (
        SceneId,
        SceneId,
        tze_hud_protocol::session_server::InputEventReceiver,
    ) {
        let mut scene = SceneGraph::new(1920.0, 1080.0);
        let tab_id = scene.create_tab("Main", 0).unwrap();
        let lease_id = scene.grant_lease("scroll-agent", 60_000);
        let focused_tile = scene
            .create_tile(
                tab_id,
                "scroll-agent",
                lease_id,
                Rect::new(0.0, 0.0, 400.0, 300.0),
                1,
            )
            .unwrap();
        let pointer_tile = scene
            .create_tile(
                tab_id,
                "scroll-agent",
                lease_id,
                Rect::new(500.0, 0.0, 400.0, 300.0),
                1,
            )
            .unwrap();
        scene
            .register_tile_scroll_config(focused_tile, tze_hud_scene::TileScrollConfig::vertical())
            .unwrap();
        scene
            .register_tile_scroll_config(pointer_tile, tze_hud_scene::TileScrollConfig::vertical())
            .unwrap();

        harness.app.state.focus_manager.add_tab(tab_id);
        let transition =
            harness
                .app
                .state
                .focus_manager
                .on_click(tab_id, focused_tile, None, &scene);
        assert!(
            transition.gained.is_some(),
            "test setup must focus first tile"
        );
        harness.app.state.cursor_x = 550.0;
        harness.app.state.cursor_y = 50.0;

        {
            let shared = harness.app.state.shared_state.blocking_lock();
            *shared.scene.blocking_lock() = scene;
        }
        *harness.app.state.active_tab_mirror.lock().unwrap() = Some(tab_id);

        let tx = tze_hud_protocol::session_server::InputEventSender::new(16);
        let rx = tx.subscribe_all();
        harness.app.state.input_event_tx = Some(tx);
        (focused_tile, pointer_tile, rx)
    }

    /// RFC 0007 §2.3 / system-shell "Tab Keyboard Shortcuts": the runtime
    /// consumes Ctrl+Tab before agent routing and changes the authoritative
    /// scene tab locally. Drive the real event-loop drain so this proves the
    /// production precedence seam, not only `shell::handle_shortcut` in
    /// isolation.

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn poc_portal_viewer_dismiss_then_mcp_verbs() {
    let publish = json!({"surface": PORTAL, "content": "Working."});
    let mut poc = Poc::boot().await;
    poc.call("hud_publish", publish.clone()).await;
    assert_eq!(poc.hud.tile_count(), 1);

    poc.hud.viewer_dismiss_all_tiles();
    poc.settle().await;
    assert_eq!(poc.hud.tile_count(), 0, "the viewer's dismiss is immediate");

    let hold = poc
        .call_err("hud_hold", json!({"surface": PORTAL, "ttl_ms": 1_000}))
        .await;
    assert_eq!(hold, "NOT_HELD");

    // hud_hold dropped the stale holding; re-attach, dismiss again, and prove
    // hud_clear is a no-op success on a stale (still cached) token.
    poc.call("hud_publish", publish.clone()).await;
    assert_eq!(
        poc.hud.tile_count(),
        1,
        "publish re-attaches a fresh portal"
    );
    poc.hud.viewer_dismiss_all_tiles();
    poc.settle().await;
    let clear = poc.call("hud_clear", json!({"surface": PORTAL})).await;
    assert_eq!(clear.body, json!({"ok": true}));

    let again = poc.call("hud_publish", publish).await;
    assert_eq!(again.body, json!({"ok": true}));
    assert_eq!(
        poc.hud.tile_count(),
        1,
        "publish after clear attaches fresh"
    );
}

#[tokio::test]
async fn tile_close_button_draw_and_hit_region_share_token_geometry() {
    let (mut compositor, _surface) = require_gpu!(make_compositor_and_surface(1280, 720).await);
    compositor
        .token_map
        .insert("tile.close_button.size_px".into(), "30".into());
    compositor
        .token_map
        .insert("tile.close_button.background".into(), "#336699".into());

    let mut scene = SceneGraph::new(1280.0, 720.0);
    let tab = scene.create_tab("Main", 0).unwrap();
    let lease = scene.grant_lease("agent", 60_000);
    let tile = scene
        .create_tile(
            tab,
            "agent",
            lease,
            Rect::new(100.0, 100.0, 400.0, 300.0),
            10,
        )
        .unwrap();

    // No hover: nothing drawn, nothing to hit.
    let mut resting: Vec<crate::pipeline::RectVertex> = Vec::new();
    compositor.append_tile_close_button_vertices(&scene, &mut resting, 1280.0, 720.0);
    compositor.populate_zone_hit_regions(&mut scene, 1280.0, 720.0);
    assert!(resting.is_empty());
    assert!(scene.overlay.zone_hit_regions.is_empty());

    compositor.tile_close_hover = Some(tile);
    let mut vertices: Vec<crate::pipeline::RectVertex> = Vec::new();
    compositor.append_tile_close_button_vertices(&scene, &mut vertices, 1280.0, 720.0);
    compositor.populate_zone_hit_regions(&mut scene, 1280.0, 720.0);

    let region = scene
        .overlay
        .zone_hit_regions
        .iter()
        .find(|r| matches!(r.kind, ZoneInteractionKind::DismissTile { .. }))
        .expect("hovered tile must register a close hit region");
    let b = region.bounds;
    assert_eq!((b.width, b.height), (30.0, 30.0), "size comes from tokens");
    assert!(
        b.x + b.width <= 500.0 && b.y >= 100.0 && b.x > 100.0,
        "button sits inside the tile's top-right corner: {b:?}"
    );
    let tokens = crate::renderer::token_colors::resolve_tile_close_tokens(&compositor.token_map);
    let fill = compositor.gpu_color(tokens.background);
    let quad = crate::pipeline::rect_vertices(b.x, b.y, b.width, b.height, 1280.0, 720.0, fill);
    assert!(
        vertices.windows(6).any(|w| w
            .iter()
            .zip(&quad)
            .all(|(a, q)| a.position == q.position && a.color == q.color)),
        "token-filled quad must be drawn at the hit region bounds"
    );

    let hit = scene.hit_test(b.x + b.width / 2.0, b.y + b.height / 2.0);
    assert!(
        matches!(
            hit,
            HitResult::ZoneInteraction {
                kind: ZoneInteractionKind::DismissTile { tile_id },
                ..
            } if tile_id == tile
        ),
        "press on the button resolves to DismissTile, got {hit:?}"
    );
    assert!(
        matches!(scene.hit_test(150.0, 350.0), HitResult::TileHit { .. }),
        "the rest of the tile is unchanged"
    );
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn poc_override_safe_mode_wins_with_hung_grpc_agent() {
    let mut poc = Poc::boot().await;
    let hung = HungAgent::connect(poc.hud.grpc_addr()).await;
    assert_eq!(poc.hud.tile_count(), 1);
    let big_clear = || {
        ClientPayload::Clear(wire::Clear {
            surface: format!("zone:{}", "z".repeat(2_000)),
        })
    };
    let flood = hung.keep_sending(big_clear);
    poc.wait_until_hung("resident").await;
    let poll = poc.park_long_poll();

    poc.hud.press_safe_mode_hotkey();
    poc.wait_for("safe mode", |hud| hud.safe_mode_active())
        .await;
    assert_eq!(
        poc.hud.suspended_lease_count(),
        1,
        "the hung agent's lease is suspended"
    );
    let code = poc
        .call_err("hud_publish", json!({"surface": SUBTITLE, "content": "hi"}))
        .await;
    assert_eq!(code, "SAFE_MODE_ACTIVE");
    assert!(!poll.is_finished(), "the long-poll is still parked");

    poc.hud.press_safe_mode_hotkey();
    poc.wait_for("safe mode off", |hud| !hud.safe_mode_active())
        .await;
    assert_eq!(poc.hud.suspended_lease_count(), 0);

    poc.hud.viewer_dismiss_all_tiles();
    assert_eq!(
        poc.hud.tile_count(),
        0,
        "dismiss does not wait for the agent"
    );
    poll.abort();
    flood.abort();
}

/// The other order: the agent hangs while safe mode is on, by flooding writes
/// the runtime refuses with `SAFE_MODE_ACTIVE`. Refusing them must not hold
/// the shared state while it waits on the agent, or the human could never
/// leave safe mode.

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn poc_override_exit_safe_mode_with_agent_hung_during_it() {
    let mut poc = Poc::boot().await;
    let hung = HungAgent::connect(poc.hud.grpc_addr()).await;
    poc.hud.press_safe_mode_hotkey();
    poc.wait_for("safe mode", |hud| hud.safe_mode_active())
        .await;

    let write = || {
        ClientPayload::MutationBatch(wire::MutationBatch {
            batch_id: uuid::Uuid::now_v7().as_bytes().to_vec(),
            lease_id: vec![0; 16],
            mutations: vec![],
            timing: None,
        })
    };
    let flood = hung.keep_sending(write);
    poc.wait_until_hung("resident").await;

    poc.hud.press_safe_mode_hotkey();
    poc.wait_for("safe mode off", |hud| !hud.safe_mode_active())
        .await;
    assert_eq!(poc.hud.suspended_lease_count(), 0, "the lease resumes");
    flood.abort();
}

/// A responsive agent is told what the human did (docs/api.md): safe mode
/// arrives as `SessionSuspended` and writes are refused with `SAFE_MODE_ACTIVE`
/// until `SessionResumed`; a viewer dismiss arrives as `Reclaimed{OVERRIDE}`.

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn poc_override_notifies_the_agent() {
    let mut poc = Poc::boot().await;
    let mut agent = poc.resident().await;
    let claimed = agent
        .claim(wire::TileAnchor::TopRight, wire::TileSize::Small, "working")
        .await;

    poc.hud.press_safe_mode_hotkey();
    match next_message(&mut agent.stream).await.payload {
        Some(ServerPayload::SessionSuspended(_)) => {}
        other => panic!("expected SessionSuspended, got {other:?}"),
    }
    let refused = agent.set_text(&claimed, "ignored").await;
    assert_eq!(refused.code, "SAFE_MODE_ACTIVE");

    poc.hud.press_safe_mode_hotkey();
    match next_message(&mut agent.stream).await.payload {
        Some(ServerPayload::SessionResumed(_)) => {}
        other => panic!("expected SessionResumed, got {other:?}"),
    }
    assert!(agent.set_text(&claimed, "back").await.ok);

    poc.hud.viewer_dismiss_all_tiles();
    poc.settle().await;
    match next_message(&mut agent.stream).await.payload {
        Some(ServerPayload::Reclaimed(reclaimed)) => {
            assert_eq!(reclaimed.why, wire::ReclaimReason::Override as i32);
            assert_eq!(reclaimed.lease_id, claimed.lease);
            assert!(reclaimed.surface.starts_with("tile:"), "{reclaimed:?}");
        }
        other => panic!("expected Reclaimed, got {other:?}"),
    }
    assert_eq!(poc.hud.tile_count(), 0);
}

